var seed;
var mySize;
var palette;
var rez = 0.9;
var t = 0;

function setup() {
	seed = floor(random(999999));
	randomSeed(seed);

	mySize = max(windowWidth, windowHeight);
	createCanvas(mySize, mySize, WEBGL);

	palette = random(colorScheme).colors.concat();
	background(random(bgcolor));

	frameRate(30);
}

function draw() {
	background(random(bgcolor));
	randomSeed(seed); // keep animation deterministic

	t += 0.1 / 10.5;

	push();
	translate(0, 0, -mySize * 1.0);

	rotateX(t * 0.1);
	rotateY(t * 0.3);
	rotateZ(t * 0.2);

	let cubeSize = abs(mySize * 2.5 / 10.5 - t * 0);
	let step = cubeSize / 1;

	for (let x = -cubeSize / 2; x <= cubeSize / 2; x += step) {
		let rot = 10 * TAU * 0.1;
		rotateX(rot);
		rotateY(rot);
		rotateZ(rot);
		for (let y = -cubeSize / 2; y <= cubeSize / 2; y += step) {
			rot = 2 * TAU * 0.1;
			rotateX(rot);
			rotateY(rot);
			rotateZ(rot);
			for (let z = -cubeSize / 2; z <= cubeSize / 2; z += step) {
				rot = 3 * TAU * 0.1;
				rotateX(rot);
				rotateY(rot);
				rotateZ(rot);

				let n = noise(x * rez, y * rez, z * rez + t) / 1;

				push();
				translate(x, y, z);

				rot = n * TAU * 0.1;
				rotateX(rot);
				rotateY(rot * 0.8);
				rotateZ(rot * 0.6);

				fill(random(palette));
				noStroke();
				// plane(mySize/1*random(n) + n * 1*random(n));
				let px = n / random(1, int(TAU)) / 1 / sin(n);
				let py = n / random(1, int(TAU)) / 1 / cos(n);
				let pz = n / random(1, int(TAU)) / 1 / tan(n);
				push();
				translate(px, py, pz);
				rotateX(rot + random(t));
				rotateY(rot * 1.8 + random(t));
				rotateZ(rot * 0.6 + random(t));
				let sphere_r = random(mySize / 50, mySize / 20 * random(1, n));
				sphere(sphere_r);
				// plane(random(mySize / 8 * random(n), mySize / 4 * random(n)));

				//line-ring
				let linering_num = int(random(20, 100));
				let linering_h = mySize / 100 / sphere_r * (20 - linering_num) - 0; // sphere_r / 1;
				let linering_r = mySize / 50 * sphere_r * 1;
				for (let a = 0; a < linering_num; a++) {
					noFill();
					stroke(random(palette));
					strokeWeight(2 * random(0.1, 5));
					push();
					translate(0, -linering_h, 0);
					rotateY(a * TAU / linering_num * 1 / 1)
					line(linering_r, 0, linering_r, linering_h * 2);
					pop();
				}

				noFill();
				stroke(random(palette));
				strokeWeight(random(0.5, 5));
				let a = mySize / 10;
				rotateX(rot + random(t) + t);
				rotateY(rot * 1.8 + random(t));
				rotateZ(rot * 0.6 + random(t));
				// let a = random(mySize / 2 * random(n), mySize / 2 * random(n));
				line(a, 0, 0, a, a, a);
				// line(0, a, 0, a, a, a);
				// line(0, 0, a, a, a, a);
				pop();
				pop();
			}
		}
	}

	pop();
}
